        ProjectColorDefinition(key: "slate", label: "Grau", hex: 0x8E8E93),
        ProjectColorDefinition(key: "blue", label: "Blau", hex: 0x4A7FD4),
        ProjectColorDefinition(key: "teal", label: "Petrol", hex: 0x3A9A9A),
        ProjectColorDefinition(key: "green", label: "Grün", hex: 0x4F9A5C),
        ProjectColorDefinition(key: "amber", label: "Ocker", hex: 0xC49A3A),
        ProjectColorDefinition(key: "orange", label: "Orange", hex: 0xD2793F),
        ProjectColorDefinition(key: "red", label: "Rot", hex: 0xC95353),
        ProjectColorDefinition(key: "pink", label: "Rosa", hex: 0xC46A93),
        ProjectColorDefinition(key: "purple", label: "Violett", hex: 0x8A6CC4),
    ]

    /// Unknown keys fall back to grey (as on the web).
    public static func forKey(_ key: String) -> ProjectColorDefinition {
